   "original": "Das Internet ist ein <strong>dezentral organisiertes globales Computernetz</strong> aus vielen miteinander verbundenen Teilnetzen. Die Datenübertragung stützt sich auf die TCP/IP-Protokollfamilie bzw. kompatible Protokolle."
