    "<strong>Die Stutzenreihe am Messingrohr</strong> — mal genügt ein Hahn, mal müssen zwei zugleich offen stehen → <em>ein oder mehrere Netzprotokolle</em>",
    "<strong>Die angelehnte Bretterbude</strong> — dasselbe Wasser, kein Zeichen des Hauses, nimmt die Muschel nicht → <em>Webservices sind keine Netzdienste</em>"
