   "merksatz": "Am Kammerkopf steht die Reihe, in der auch ein Karren selbst anstösst, der Sims nimmt die Muschel und die Öffnung gibt den vollen Krug zurück, mehr als das Klappern unten und den anlaufenden Stein hat der türlose Klotz nicht anzubieten, drinnen aber zischen die Hähne einzeln oder zu zweit — und die angelehnte Bude nebenan gehört nicht dazu.",
   "original": "Stellt Anwendern oder teilnehmenden Geräten einen Service zur Kommunikation oder gemeinsamen Ressourcennutzung bereit. Aus Anwendersicht eine in sich geschlossene Funktionskomponente, technisch über ein oder mehrere Netzprotokolle realisiert. Webservices basieren zwar auf Netzen, sind aber keine Netzdienste in diesem Sinne."
